/*updateBuyerMdAmBudgetCompilation*/
	UPDATE ICOMBDGT SET										      
		PLAN_AMT		= #{st_plan_amt},
		REMARK			= #{st_remark},
		PLAN_DATE		= TO_CHAR(SYSDATE,'YYYYMMDD')
	WHERE 1=1					      


		AND BUYER			= #{st_buyer_code}  						     


		AND BUYER			= #{st_com_code}  						     


	AND DEPT			= #{db_dept}	      
	AND ACCOUNT_TYPE	= #{db_account_type}      
	AND TERM			= #{db_term}

/*deleteBuyerMdAmBudgetCompilation*/ DELETE ICOMBDGT WHERE 1=1
AND BUYER = #{st_buyer_code}
AND BUYER = #{st_com_code}
AND DEPT = #{db_dept} AND ACCOUNT_TYPE = #{db_account_type} AND TERM = #{db_term}

/*mergeBuyerMdAmBudgetCompilation_v2*/ MERGE INTO ICOMBDGT USING DUAL ON (
BUYER = #{st_buyer_code}
BUYER = #{st_com_code}
AND DEPT = #{DEPT} AND ACCOUNT_TYPE = #{ACCOUNT_TYPE} AND TERM = #{TERM} ) WHEN MATCHED THEN UPDATE SET PLAN_AMT = #{PLAN_AMT}, REMARK = #{REMARK}, PLAN_DATE = TO_CHAR(SYSDATE,'YYYYMMDD') WHEN NOT MATCHED THEN INSERT ( BUYER, DEPT, ACCOUNT_TYPE, TERM_TYPE, TERM, FROM_DATE, TO_DATE, PLAN_AMT, PLAN_DATE, BALANCE_AMT, REMARK, ADD_USER_ID )VALUES(
#{st_buyer_code},
#{st_com_code},
#{DEPT}, #{ACCOUNT_TYPE}, #{TERM_TYPE}, #{TERM}, #{FROM_DATE}, #{TO_DATE}, #{PLAN_AMT}, TO_CHAR(SYSDATE,'YYYYMMDD'), 0, #{REMARK}, #{st_user_id} )


        /*delBuyerMdAmBudgetCompilationList_v2*/
	      DELETE ICOMBDGT 
		WHERE 1=1					      


				AND BUYER			= #{st_buyer_code}  						     


				AND BUYER			= #{st_com_code}  						     


			AND DEPT			= #{DEPT}
			AND ACCOUNT_TYPE	= #{ACCOUNT_TYPE}
			AND TERM_TYPE = #{TERM_TYPE}
			AND #{st_from_date} <= FROM_DATE  AND #{st_to_date} >= TO_DATE

mapper.select:
/*selectBuyerMdAmBudgetCompilationListData_v2*/ SELECT DEPT ,ACCOUNT_TYPE ,TERM ,TERM_TYPE ,FROM_DATE ,TO_DATE ,PLAN_AMT ,PLAN_AMT AS ORG_PLAN_AMT ,RESULT_AMT ,TEMP_AMT ,LAST_RESULT_DATE ,REMARK ,BALANCE_AMT ,VIEW_FLAG FROM ICOMBDGT WHERE 1=1
AND BUYER = #{st_buyer_code}
AND BUYER = #{st_com_code}
AND DEPT = #{DEPT} AND ACCOUNT_TYPE = #{ACCOUNT_TYPE} AND TERM_TYPE = #{TERM_TYPE} AND #{st_from_date} <= FROM_DATE AND #{st_to_date} >= TO_DATE
